import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"Graceful shutdown","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workers/graceful-shutdown.md","filePath":"guide/workers/graceful-shutdown.md","lastUpdated":1785480634000}`),a={name:`guide/workers/graceful-shutdown.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="graceful-shutdown" tabindex="-1">Graceful shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to “Graceful shutdown”">​</a></h1><p>BullMQ supports graceful shutdowns of workers. This is important so that we can minimize stalled jobs when a worker for some reason must be shutdown. But note that even in the event of a &quot;ungraceful shutdown&quot;, the stalled mechanism in BullMQ allows for new workers to pick up stalled jobs and continue working on them.</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>Prior to BullMQ 2.0, in order for stalled jobs to be picked up by other workers you need to have a <a href="./../queuescheduler"><code>QueueScheduler</code></a> class running in the system.</p><p>From BullMQ 2.0 and onwards, the <code>QueueScheduler</code> is not needed anymore, so the information above is only valid for older versions.</p></div><p>In order to perform a shutdown just call the <em><strong><code>close</code></strong></em> method:</p><div class="language-typescript"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> worker.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">close</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>The above call will mark the worker as <em>closing</em> so it will not pick up new jobs, and at the same time it will wait for all the current jobs to be processed (or failed). This call will not timeout by itself, so you should make sure that your jobs finalize in a timely manner. If this call fails for some reason or it is not able to complete, the pending jobs will be marked as stalled and processed by other workers (if correct stalled options are configured on the <a href="https://docs.bullmq.io/api/interfaces/v1.QueueSchedulerOptions.html" target="_blank" rel="noreferrer"><code>QueueScheduler</code></a>).</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};